    "titleEn": "Equilibrium Constant Kc Calculation #1",
    "titleAr": "حساب ثابت الاتزان Kc للتفاعل الغازي #1",
    "difficulty": "medium",
    "questionEn": "For the reversible gas reaction: $\\text{A}_{\\text{(g)}} + \\text{B}_{\\text{(g)}} \\rightleftharpoons 2\\text{C}_{\\text{(g)}}$, equilibrium concentrations are determined to be $[\\text{A}] = 1\\text{ M}$, $[\\text{B}] = 2\\text{ M}$, and $[\\text{C}] = 4\\text{ M}$. Calculate the equilibrium constant $K_c$.",
    "questionAr": "للتفاعل الغازي الانعكاسي: $\\text{A}_{\\text{(g)}} + \\text{B}_{\\text{(g)}} \\rightleftharpoons 2\\text{C}_{\\text{(g)}}$، وجد أن التراكيز عند الاتزان هي $[\\text{A}] = 1\\text{ M}$، و $[\\text{B}] = 2\\text{ M}$، و $[\\text{C}] = 4\\text{ M}$. احسب قيمة ثابت الاتزان $K_c$.",
    "optionsEn": [
      "$K_c = 8$",
      "$K_c = 16$",
      "$K_c = 4.0$",
      "$K_c = 2$"
    ],
