    "questionEn": "A buffer solution contains acetic acid and sodium acetate with a salt-to-acid molar ratio of $\\frac{[\\text{CH}_3\\text{COONa}]}{[\\text{CH}_3\\text{COOH}]} = 1$. If $pK_a = 4.74$, calculate the $\\text{pH}$ of this buffer.",
    "questionAr": "محلول منظم يتكون من حمض الأسيتيك وأسيتات الصوديوم بنسبة تركيز ملح إلى حمض تساوي $\\frac{[\\text{CH}_3\\text{COONa}]}{[\\text{CH}_3\\text{COOH}]} = 1$. إذا كانت $pK_a = 4.74$، فما قيمة $\\text{pH}$ لهذا المحلول المنظم؟",
